import{_ as o,o as t,c as r,ag as a}from"./chunks/framework.7BZpJk9v.js";const y=JSON.parse('{"title":"Put your website live on your domain","description":"","frontmatter":{},"headers":[],"relativePath":"your-domain.md","filePath":"your-domain.md"}'),i={name:"your-domain.md"};function d(n,e,s,l,c,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="put-your-website-live-on-your-domain" tabindex="-1">Put your website live on your domain <a class="header-anchor" href="#put-your-website-live-on-your-domain" aria-label="Permalink to &quot;Put your website live on your domain&quot;">​</a></h1><p>We host your new website. You keep your domain. To go live, your domain needs to point to us. That takes a few DNS records, added once.</p><h2 id="_1-tell-us-about-your-domain" tabindex="-1">1. Tell us about your domain <a class="header-anchor" href="#_1-tell-us-about-your-domain" aria-label="Permalink to &quot;1. Tell us about your domain&quot;">​</a></h2><p>In <strong>Launch Setup</strong> in your portal, fill in <strong>Website And Domain</strong>:</p><ul><li>the domain, for example <code>yourbrand.com</code>, or a subdomain such as <code>franchise.yourbrand.com</code></li><li>where it is registered, for example GoDaddy, Cloudflare or Squarespace</li><li>who can change its DNS, with their email</li></ul><h2 id="_2-add-the-records-we-send-you" tabindex="-1">2. Add the records we send you <a class="header-anchor" href="#_2-add-the-records-we-send-you" aria-label="Permalink to &quot;2. Add the records we send you&quot;">​</a></h2><p>When your Final Kit is approved, we email you the records, with the subject <strong>Three Records To Put [your brand] Live</strong>. Forward it to whoever manages the domain. They add the records at your domain provider, in its DNS settings.</p><p>The email has the exact values. A typical set looks like this:</p><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Value</th></tr></thead><tbody><tr><td><code>A</code></td><td><code>@</code></td><td><code>76.76.21.21</code></td></tr><tr><td><code>CNAME</code></td><td><code>www</code></td><td><code>cname.vercel-dns.com</code></td></tr><tr><td><code>TXT</code></td><td><code>_vercel</code></td><td>a code, only if our email lists one</td></tr></tbody></table><p>A subdomain such as <code>franchise.yourbrand.com</code> needs only one <code>CNAME</code>, with the name <code>franchise</code>.</p><ul><li><strong>Replace</strong> the <code>A</code> record for <code>@</code> and the <code>CNAME</code> for <code>www</code> if they exist. Your old site stops when you do this, so add the records when you are ready to switch.</li><li><strong>Do not change</strong> your <code>MX</code> records or other <code>TXT</code> records. They run your email.</li><li><strong>On Cloudflare</strong>, set each record to <strong>DNS only</strong> (grey cloud), not Proxied.</li></ul><p>Prefer not to do it yourself? Reply to our email, give us access to your DNS, and we add the records for you.</p><h2 id="_3-we-check-it-and-put-it-live" tabindex="-1">3. We check it and put it live <a class="header-anchor" href="#_3-we-check-it-and-put-it-live" aria-label="Permalink to &quot;3. We check it and put it live&quot;">​</a></h2><p>When the records are in, we:</p><ul><li>connect the domain and turn on HTTPS, automatically and free</li><li>check that every form sends its leads to your pipeline</li><li>check your tags: Google Tag Manager, Google Analytics and the Meta pixel</li></ul><p>Then we email you that your site is live. DNS changes usually show within an hour. Some providers take up to 48 hours.</p><h2 id="if-something-looks-wrong" tabindex="-1">If something looks wrong <a class="header-anchor" href="#if-something-looks-wrong" aria-label="Permalink to &quot;If something looks wrong&quot;">​</a></h2><ul><li><strong>The old site still shows:</strong> your device may still have the old address. Wait an hour, or try on your phone with Wi-Fi off.</li><li><strong>A security warning shows:</strong> the HTTPS certificate is still being issued. This takes a few minutes after the records are in.</li><li><strong>Email stopped working:</strong> an <code>MX</code> or email <code>TXT</code> record was changed. Put it back as it was, then tell us.</li></ul><p>Questions at any step: reply to our email, or use <strong>Help</strong> in your portal.</p>',19)])])}const m=o(i,[["render",d]]);export{y as __pageData,m as default};
